import{_ as i,l,o as e,c as n,v as r,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"内点法直觉","description":"","frontmatter":{"title":"内点法直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interior-point.md","filePath":"cs/interior-point.md","lastUpdated":1789023840000}'),m={name:"cs/interior-point.md"};function c(_,a,u,P,E,f){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="内点法直觉" tabindex="-1">内点法直觉 <a class="header-anchor" href="#内点法直觉" aria-label="Permalink to &quot;内点法直觉&quot;">​</a></h1><div class="epigraph"><p>不沿顶点走，而在可行域内部沿中心路径逼近最优；多项式次牛顿即可到给定精度。</p><footer>—— 据 Karmarkar, A New Polynomial-Time Algorithm for Linear Programming, 1984；Nesterov and Nemirovski 内点理论整理</footer></div><p>上一课<a href="/cs/branch-and-bound">分支定界</a>为整数离开多面体内部。连续 LP 还有内点：障碍函数 \\(-\\sum\\log x_i\\) 把边界推开，牛顿跟中心路径。缺口是这幅几何，不是 Karmarkar 原文的射影变换细节。不重写单纯形转轴。后课素数筛离开优化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单纯形最坏指数，平均快。椭球法多项式但慢。内点：最小化 \\(c^\\top x-\\mu\\sum\\log x_i\\)（对数障碍），\\(\\mu\\to 0\\) 时趋向最优面。每步牛顿解 KKT 线性系统（正规方程），\\(\\mu\\) 按比例减小。多项式迭代，与输入位数和精度有关。</p><p>缺口是「内部路径」，不是再列顶点。</p><h3 id="不是梯度下降课" tabindex="-1">不是梯度下降课 <a class="header-anchor" href="#不是梯度下降课" aria-label="Permalink to &quot;不是梯度下降课&quot;">​</a></h3><p>约束是不等式，投影或障碍才保可行。无约束光滑优化的梯度/牛顿不自动处理 \\(Ax=b\\)。本课 LP 内点。</p><p><span class="marginnote">Karmarkar 1984。现代障碍/原始–对偶内点见 Nesterov–Nemirovski。实践中 LP 内点与单纯形竞争。后课筛法换数论对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>严格可行内点出发（或不可行内点变体）。短步或长步减小 \\(\\mu\\)。解牛顿系统（稀疏 Cholesky）。终止：对偶间隙小。</p>',11)),(e(),s(h,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MU%5B%22%E9%9A%9C%E7%A2%8D%E5%8F%82%E6%95%B0%20%CE%BC%22%5D%20--%3E%20NT%5B%22%E7%89%9B%E9%A1%BF%E6%AD%A5%22%5D%0A%20%20NT%20--%3E%20PATH%5B%22%E4%B8%AD%E5%BF%83%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PATH%20--%3E%20OPT%5B%22%CE%BC%E2%86%920%20%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>二次锥、半定规划同源障碍，点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自和谐障碍保证牛顿步二次收敛于中心。与单纯形：最坏多项式 vs 实用顶点。与对偶：原始–对偶内点同时更新 \\(x,y,s\\)。数值核心是线性系统，接上一课高斯的稀疏版。</p><p>不要对 ILP 直接内点当精确整数解——仍要舍入或分支。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证自和谐。不写全部 Mehrotra 预测校正。后课默认：LP 多项式可解（内点/椭球）；单纯形仍常用。下一课素数筛。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对数障碍中心路径 + 牛顿。</li><li>连续 LP 多项式时间。</li><li>整数问题仍要舍入或分支。</li><li>出处：Karmarkar, 1984。</li></ul>',8))])}const b=i(m,[["render",c]]);export{T as __pageData,b as default};
